def hunks(path):
    out=subprocess.run(['git','diff','-U0',BASE,NEW,'--',path],capture_output=True,text=True).stdout
    hs=[]
    for m in re.finditer(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@',out,re.M):
        a=int(m.group(1)); b=int(m.group(2)) if m.group(2) is not None else 1
        c=int(m.group(3)); d=int(m.group(4)) if m.group(4) is not None else 1
        hs.append((a,b,c,d))
    return hs
cache={}
def mapline(f,l):
    path={'FlatString.fss':'Library/FlatString.fss'}.get(f)
    import os
    for p in ['Library/'+f,'ProjectFortress/LibraryBuiltin/'+f]:
        if os.path.exists(p): path=p;break
    if path not in cache: cache[path]=hunks(path)
    off=0
    for a,b,c,d in cache[path]:
        start=a if b>0 else a+1
        if b>0 and a<=l<a+b: return None  # changed line
        if l>=start+ (b if b>0 else 0) and b>0: off=(c+d)-(a+b)
        elif b==0 and l>a: off=(c+d)-(a+b)+0
    # recompute properly
    off=0
    for a,b,c,d in cache[path]:
        if b==0:
            if l>a: off+=d
        else:
            if l>=a+b: off+=d-b
    return l+off
def load(fn):
    rows=[]
    for line in open(fn):
        if line.startswith('#'): continue
        p=line.rstrip('\n').split('\t')
        rows.append(p)
    return rows
old=load('tmp/rev12/sites11.tsv'); new=load('tmp/rev12/sites12.tsv')
def key(p):
    return p[5]
newc=collections.Counter(key(p) for p in new)
oldmapped=[]
for p in old:
    locs=p[5].split(',')
    ml=[]
    for loc in locs:
        f,l=loc.split(':'); l=int(l)
        m=mapline(f,l)
        ml.append(f+':'+(str(m) if m is not None else 'CHG%d'%l))
    oldmapped.append((','.join(ml),p))
oc=collections.Counter(k for k,_ in oldmapped)
gone=[]; 
nc=newc.copy()
for k,p in oldmapped:
    if nc[k]>0: nc[k]-=1
    else: gone.append((k,p))
came=[k for k,v in nc.items() for _ in range(v)]
print('gone',len(gone))
for k,p in gone: print('  -',k,p[0],p[2],p[6][:110])
print('came',len(came))
for k in came:
    for p in new:
        if p[5]==k: print('  +',k,p[0],p[2],p[6][:110]);break
