import json,glob,sys,re
W=sys.argv[1]; tot=0
for f in sorted(glob.glob(W+'/agent-*.jsonl')):
    lab=json.load(open(f.replace('.jsonl','.meta.json')))['description']
    recs=[]
    for line in open(f,errors='replace'):
        try:r=json.loads(line)
        except: continue
        recs.append(r)
    # map tool_use id -> is skill read
    skill_ids=set(); 
    for r in recs:
        m=r.get('message')
        if not isinstance(m,dict): continue
        c=m.get('content')
        if not isinstance(c,list): continue
        for b in c:
            if b.get('type')=='tool_use':
                inp=json.dumps(b.get('input'))
                if b['name']=='Skill' or re.search(r'\.claude/skills/fortress-repo',inp) and re.search(r'cat |sed -n|Read|head',b['name']+inp) and b['name'] in ('Read','Bash'):
                    skill_ids.add(b['id'])
    # find assistant messages following a user message containing those results
    pending=False; seen=set(); w=0; n=0
    for r in recs:
        m=r.get('message')
        if not isinstance(m,dict): continue
        if r.get('type')=='user':
            c=m.get('content')
            if isinstance(c,list) and any(b.get('type')=='tool_result' and b.get('tool_use_id') in skill_ids for b in c): pending=True; n+=1
        elif r.get('type')=='assistant' and pending and 'usage' in m:
            mid=m.get('id')
            if mid not in seen:
                seen.add(mid); u=m['usage']; w+=u.get('input_tokens',0)+u.get('cache_creation_input_tokens',0)
            pending=False
    tot+=w
    print(f"{lab:10} skill reads {len(skill_ids):3} writes {w/1e3:6.0f}K")
print(f"total {tot/1e6:.2f}M")
EOF
